        <div id="pbar" class="absolute bottom-0 left-0 right-0 h-3 cursor-pointer"><div class="absolute bottom-0 left-0 right-0 h-[3px] bg-white/25"><div id="pcur" class="h-full w-0 bg-brand"></div></div></div>
